// src/utils/StorageManager.js
import AsyncStorage from '@react-native-async-storage/async-storage';

const STORAGE_KEYS = {
  WORKOUT_HISTORY: '@workout_history',
  EXERCISE_HISTORY: '@exercise_history',
  ONE_REP_MAXES: '@one_rep_maxes',
  SETTINGS: '@settings',
  USER_STATS: '@user_stats'
};

class StorageManager {
  // Generic storage methods
  static async saveData(key, data) {
    try {
      const jsonData = JSON.stringify(data);
      await AsyncStorage.setItem(key, jsonData);
      return true;
    } catch (error) {
      console.error(`Error saving data to ${key}:`, error);
      return false;
    }
  }

  static async loadData(key, defaultValue = null) {
    try {
      const jsonData = await AsyncStorage.getItem(key);
      if (jsonData !== null) {
        const data = JSON.parse(jsonData);
        return data;
      }
      return defaultValue;
    } catch (error) {
      console.error(`Error loading data from ${key}:`, error);
      return defaultValue;
    }
  }

  static async removeData(key) {
    try {
      await AsyncStorage.removeItem(key);
      console.log(`Removed data from ${key}`);
      return true;
    } catch (error) {
      console.error(`Error removing data from ${key}:`, error);
      return false;
    }
  }

  // Specific data methods
  static async saveWorkoutHistory(workoutHistory) {
    return await this.saveData(STORAGE_KEYS.WORKOUT_HISTORY, workoutHistory);
  }

  static async loadWorkoutHistory() {
    return await this.loadData(STORAGE_KEYS.WORKOUT_HISTORY, []);
  }

  static async saveExerciseHistory(exerciseHistory) {
    return await this.saveData(STORAGE_KEYS.EXERCISE_HISTORY, exerciseHistory);
  }

  static async loadExerciseHistory() {
    return await this.loadData(STORAGE_KEYS.EXERCISE_HISTORY, {});
  }

  static async saveOneRepMaxes(oneRepMaxes) {
    return await this.saveData(STORAGE_KEYS.ONE_REP_MAXES, oneRepMaxes);
  }

  static async loadOneRepMaxes() {
    return await this.loadData(STORAGE_KEYS.ONE_REP_MAXES, {});
  }

  static async saveSettings(settings) {
    return await this.saveData(STORAGE_KEYS.SETTINGS, settings);
  }

  static async loadSettings() {
    const defaultSettings = {
      units: 'lbs',
      notifications: true,
      darkMode: false,
      autoTimer: true,
      exportFormat: 'JSON'
    };
    return await this.loadData(STORAGE_KEYS.SETTINGS, defaultSettings);
  }

  static async saveUserStats(stats) {
    return await this.saveData(STORAGE_KEYS.USER_STATS, stats);
  }

  static async loadUserStats() {
    const defaultStats = {
      totalWorkouts: 0,
      totalDuration: 0,
      favoriteExercises: [],
      streaks: {
        current: 0,
        best: 0,
        lastWorkout: null
      },
      experience: 0,
      level: 1,
      totalExperience: 0
    };
    return await this.loadData(STORAGE_KEYS.USER_STATS, defaultStats);
  }

  // Data export/import methods
  static async exportAllData() {
    try {
      const exportData = {
        workoutHistory: await this.loadWorkoutHistory(),
        exerciseHistory: await this.loadExerciseHistory(),
        oneRepMaxes: await this.loadOneRepMaxes(),
        settings: await this.loadSettings(),
        userStats: await this.loadUserStats(),
        exportDate: new Date().toISOString(),
        appVersion: '1.0.0'
      };
      
      console.log('Exported all data:', exportData);
      return exportData;
    } catch (error) {
      console.error('Error exporting data:', error);
      return null;
    }
  }

  static async importAllData(importData) {
    try {
      if (!importData || typeof importData !== 'object') {
        throw new Error('Invalid import data format');
      }

      // Validate data structure
      const requiredKeys = ['workoutHistory', 'exerciseHistory', 'oneRepMaxes', 'settings', 'userStats'];
      const missingKeys = requiredKeys.filter(key => !(key in importData));
      
      if (missingKeys.length > 0) {
        console.warn('Missing keys in import data:', missingKeys);
      }

      // Import each data type with fallbacks
      await this.saveWorkoutHistory(importData.workoutHistory || []);
      await this.saveExerciseHistory(importData.exerciseHistory || {});
      await this.saveOneRepMaxes(importData.oneRepMaxes || {});
      await this.saveSettings(importData.settings || {});
      await this.saveUserStats(importData.userStats || {});

      console.log('Successfully imported all data');
      return true;
    } catch (error) {
      console.error('Error importing data:', error);
      return false;
    }
  }

  // Clear all data (for settings screen)
  static async clearAllData() {
    try {
      await Promise.all([
        this.removeData(STORAGE_KEYS.WORKOUT_HISTORY),
        this.removeData(STORAGE_KEYS.EXERCISE_HISTORY),
        this.removeData(STORAGE_KEYS.ONE_REP_MAXES),
        this.removeData(STORAGE_KEYS.SETTINGS),
        this.removeData(STORAGE_KEYS.USER_STATS)
      ]);
      console.log('Cleared all data');
      return true;
    } catch (error) {
      console.error('Error clearing data:', error);
      return false;
    }
  }

  // Reset to dummy data with proper format
  static async resetToDummyData() {
    try {
      // Clear existing data
      await this.clearAllData();

      // Create dummy workout data with proper workoutDate format
      const dummyWorkouts = [
        {
          id: '1',
          startTime: '2025-01-15T12:00:00.000Z',
          endTime: '2025-01-15T13:30:00.000Z',
          workoutDate: '2025-01-15',
          duration: 90,
          exercises: [
            {
              id: '1-1',
              name: 'Bench Press',
              sets: [
                { reps: 8, weight: 135 },
                { reps: 8, weight: 135 },
                { reps: 6, weight: 145 }
              ]
            },
            {
              id: '1-2',
              name: 'Squats',
              sets: [
                { reps: 10, weight: 185 },
                { reps: 10, weight: 185 },
                { reps: 8, weight: 195 }
              ]
            }
          ],
          notes: 'Great workout! Felt strong today.',
          ratings: {
            workoutRating: 8,
            beforeMood: 7,
            afterMood: 9,
            beforeEnergy: 6,
            afterEnergy: 8
          },
          lastModified: '2025-01-15T13:30:00.000Z'
        },
        {
          id: '2',
          startTime: '2025-01-17T14:00:00.000Z',
          endTime: '2025-01-17T15:15:00.000Z',
          workoutDate: '2025-01-17',
          duration: 75,
          exercises: [
            {
              id: '2-1',
              name: 'Deadlifts',
              sets: [
                { reps: 5, weight: 225 },
                { reps: 5, weight: 225 },
                { reps: 3, weight: 245 }
              ]
            },
            {
              id: '2-2',
              name: 'Pull-ups',
              sets: [
                { reps: 8, weight: 0 },
                { reps: 6, weight: 0 },
                { reps: 5, weight: 0 }
              ]
            }
          ],
          notes: 'Deadlifts felt heavy but good form.',
          ratings: {
            workoutRating: 7,
            beforeMood: 6,
            afterMood: 8,
            beforeEnergy: 5,
            afterEnergy: 7
          },
          lastModified: '2025-01-17T15:15:00.000Z'
        },
        {
          id: '3',
          startTime: '2025-01-20T10:30:00.000Z',
          endTime: '2025-01-20T11:45:00.000Z',
          workoutDate: '2025-01-20',
          duration: 75,
          exercises: [
            {
              id: '3-1',
              name: 'Running',
              cardioData: {
                duration: 30,
                pace: '8:30',
                calories: 320
              }
            },
            {
              id: '3-2',
              name: 'Push-ups',
              sets: [
                { reps: 15, weight: 0 },
                { reps: 12, weight: 0 },
                { reps: 10, weight: 0 }
              ]
            }
          ],
          notes: 'Good cardio session followed by bodyweight work.',
          ratings: {
            workoutRating: 8,
            beforeMood: 6,
            afterMood: 9,
            beforeEnergy: 6,
            afterEnergy: 8
          },
          lastModified: '2025-01-20T11:45:00.000Z'
        }
      ];

      // Save dummy data
      await this.saveWorkoutHistory(dummyWorkouts);
      
      // Create dummy user stats
      const dummyStats = {
        totalWorkouts: 3,
        totalDuration: 240,
        averageRating: 7.7,
        currentStreak: 3,
        longestStreak: 3,
        experience: 150,
        level: 2,
        totalExperience: 150,
      };
      
      await this.saveUserStats(dummyStats);
      
      // Create dummy exercise history
      const dummyExerciseHistory = {
        'Bench Press': [
          { date: '2025-01-15', reps: 8, weight: 135, sets: 3 }
        ],
        'Squats': [
          { date: '2025-01-15', reps: 10, weight: 185, sets: 3 }
        ],
        'Deadlifts': [
          { date: '2025-01-17', reps: 5, weight: 225, sets: 3 }
        ],
        'Pull-ups': [
          { date: '2025-01-17', reps: 8, weight: 0, sets: 3 }
        ],
        'Running': [
          { date: '2025-01-20', duration: 30, pace: '8:30', calories: 320 }
        ],
        'Push-ups': [
          { date: '2025-01-20', reps: 15, weight: 0, sets: 3 }
        ]
      };
      
      await this.saveExerciseHistory(dummyExerciseHistory);
      
      console.log('Reset to dummy data completed');
    } catch (error) {
      console.error('Error resetting to dummy data:', error);
    }
  }
}

export default StorageManager;
